class TestQueueLifecycle:
    """Validates queue initialization, capacity, and overflow behavior."""

    def test_queue_initialized_with_maxsize(self, service, mock_settings):
        """Queue must respect configured max size."""
        assert service.telemetry_queue.maxsize == mock_settings.TELEMETRY_QUEUE_MAX_SIZE
        assert service.telemetry_queue.empty()

    def test_ingest_adds_to_queue(self, service, sample_telemetry):
        """Ingest must enqueue telemetry and update metric."""
        with patch.object(TELEMETRY_INGESTED_COUNT, "inc") as mock_inc:
            service.ingest(sample_telemetry)
            assert service.telemetry_queue.qsize() == 1
            mock_inc.assert_called_once()

    def test_ingest_queue_full_raises(self, service, sample_telemetry, mock_settings):
        """Queue overflow must raise QueueFull and not lose data."""
        # Fill queue to capacity
        for _ in range(mock_settings.TELEMETRY_QUEUE_MAX_SIZE):
            service.ingest(sample_telemetry)

        with pytest.raises(asyncio.QueueFull):
            service.ingest(sample_telemetry)

        # Verify queue size unchanged
        assert service.telemetry_queue.qsize() == mock_settings.TELEMETRY_QUEUE_MAX_SIZE

    def test_ingest_queue_full_nonblocking(self, service, sample_telemetry, mock_settings):
        """Ingest must be non-blocking on full queue."""
        for _ in range(mock_settings.TELEMETRY_QUEUE_MAX_SIZE):
            service.ingest(sample_telemetry)

        start = asyncio.get_event_loop().time()
        with pytest.raises(asyncio.QueueFull):
            service.ingest(sample_telemetry)
        elapsed = asyncio.get_event_loop().time() - start
        assert elapsed < 0.1  # Must fail immediately, not block

    def test_queue_size_metric_updated(self, service, sample_telemetry):
        """Queue size gauge must reflect current queue depth."""
        with patch.object(TELEMETRY_QUEUE_SIZE, "set") as mock_set:
            service.ingest(sample_telemetry)
            mock_set.assert_called_with(1)

    def test_ingest_rejects_invalid_type(self, service):
        """Type validation must reject non-telemetry objects."""
        with pytest.raises(TypeError):
            service.ingest("not-telemetry")

    def test_ingest_none_rejected(self, service):
        """None payload must be rejected."""
        with pytest.raises(ValueError):
            service.ingest(None)


