class TestProcessingPipeline:
    """Validates the async processing loop and batch handling."""

    def test_processing_task_started(self, service):
        """Processing task must be started on service start."""
        service.start_processing()
        assert service._processing_task is not None
        assert not service._processing_task.done()

    def test_processing_task_stopped(self, service):
        """Processing task must be cancellable."""
        service.start_processing()
        service.stop_processing()
        assert service._processing_task.cancelled()

    def test_processing_drains_queue(self, service, sample_telemetry):
        """Processing must drain queued items."""
        # Enqueue items
        for _ in range(3):
            service.ingest(sample_telemetry)

        service.start_processing()
        asyncio.get_event_loop().run_until_complete(asyncio.sleep(0.2))
        service.stop_processing()

        assert service.telemetry_queue.empty()

    def test_processing_batches_items(self, service, sample_telemetry, mock_settings):
        """Items must be processed in batches of configured size."""
        # Enqueue more than batch size
        for _ in range(mock_settings.PROCESSING_BATCH_SIZE + 2):
            service.ingest(sample_telemetry)

        with patch.object(service, "_process_batch", new_callable=AsyncMock) as mock_process:
            service.start_processing()
            asyncio.get_event_loop().run_until_complete(asyncio.sleep(0.2))
            service.stop_processing()

            # Verify batch sizes
            batch_sizes = [call.args[0].__len__() for call in mock_process.call_args_list]
            assert batch_sizes[0] == mock_settings.PROCESSING_BATCH_SIZE
            assert batch_sizes[1] == 2

    def test_processing_handles_empty_queue(self, service):
        """Processing must idle gracefully on empty queue."""
        service.start_processing()
        asyncio.get_event_loop().run_until_complete(asyncio.sleep(0.1))
        service.stop_processing()
        # No exception should be raised

    def test_processing_metric_incremented(self, service, sample_telemetry):
        """Processed count metric must increment per item."""
        service.ingest(sample_telemetry)
        with patch.object(TELEMETRY_PROCESSED_COUNT, "inc") as mock_inc:
            service.start_processing()
            asyncio.get_event_loop().run_until_complete(asyncio.sleep(0.2))
            service.stop_processing()
            mock_inc.assert_called()

    def test_processing_error_handling(self, service, sample_telemetry):
        """Processing errors must be logged and not crash the loop."""
        service.ingest(sample_telemetry)
        with patch.object(service, "_process_batch", new_callable=AsyncMock, side_effect=RuntimeError("boom")):
            with patch("app.services.logger.error") as mock_log:
                service.start_processing()
                asyncio.get_event_loop().run_until_complete(asyncio.sleep(0.2))
                service.stop_processing()
                mock_log.assert_called()

    def test_processing_continues_after_error(self, service, sample_telemetry):
        """Loop must continue processing after an error."""
        for _ in range(3):
            service.ingest(sample_telemetry)

        call_count = 0
        async def flaky_process(batch):
            nonlocal call_count
            call_count += 1
            if call_count == 1:
                raise RuntimeError("first failure")
            return True

        with patch.object(service, "_process_batch", new_callable=AsyncMock, side_effect=flaky_process):
            service.start_processing()
            asyncio.get_event_loop().run_until_complete(asyncio.sleep(0.3))
            service.stop_processing()

        assert call_count >= 2  # Must have retried after failure


