class TestConcurrency:
    """Validates behavior under concurrent load."""

    def test_concurrent_ingestion(self, service, sample_telemetry, mock_settings):
        """Multiple producers must safely enqueue."""
        async def producer(n):
            for _ in range(n):
                service.ingest(sample_telemetry)
                await asyncio.sleep(0.001)

        async def run():
            await asyncio.gather(
                producer(5), producer(5), producer(5)
            )

        asyncio.get_event_loop().run_until_complete(run())
        assert service.telemetry_queue.qsize() == 15

    def test_concurrent_ingestion_overflow(self, service, sample_telemetry, mock_settings):
        """Concurrent overflow must raise QueueFull for some producers."""
        async def producer(n):
            failures = 0
            for _ in range(n):
                try:
                    service.ingest(sample_telemetry)
                except asyncio.QueueFull:
                    failures += 1
                await asyncio.sleep(0.001)
            return failures

        async def run():
            results = await asyncio.gather(
                producer(20), producer(20), producer(20)
            )
            return sum(results)

        failures = asyncio.get_event_loop().run_until_complete(run())
        assert failures > 0  # Some producers must have failed
        assert service.telemetry_queue.qsize() == mock_settings.TELEMETRY_QUEUE_MAX_SIZE

    def test_processing_under_load(self, service, sample_telemetry, mock_settings):
        """Processing must keep up with sustained load."""
        # Pre-fill queue
        for _ in range(mock_settings.TELEMETRY_QUEUE_MAX_SIZE):
            service.ingest(sample_telemetry)

        with patch.object(service, "_process_batch", new_callable=AsyncMock, return_value=True):
            service.start_processing()
            # Add more while processing
            for _ in range(5):
                try:
                    service.ingest(sample_telemetry)
                except asyncio.QueueFull:
                    pass
                asyncio.get_event_loop().run_until_complete(asyncio.sleep(0.01))
            service.stop_processing()

        assert service.telemetry_queue.empty()

    def test_no_data_loss_on_breaker_open(self, service, sample_telemetry):
        """Queue must retain data when breaker is open."""
        service.ingest(sample_telemetry)
        service.anomaly_detection_breaker._state_storage.state = "open"

        service.start_processing()
        asyncio.get_event_loop().run_until_complete(asyncio.sleep(0.2))
        service.stop_processing()

        # Data must remain in queue (not processed)
        assert service.telemetry_queue.qsize() == 1


