class TestPropertyBased:
    """Property-based validation of invariant behaviors."""

    @pytest.mark.parametrize("num_items", [0, 1, 5, 10, 50])
    def test_queue_invariant_after_ingest(self, service, sample_telemetry, num_items):
        """Queue size must equal number of successful ingests."""
        for _ in range(num_items):
            service.ingest(sample_telemetry)
        assert service.telemetry_queue.qsize() == num_items

    @pytest.mark.parametrize("failures", [1, 2, 3, 4, 5])
    def test_breaker_threshold_property(self, service, sample_telemetry, failures):
        """Breaker must open exactly at threshold, not before."""
        # Reset breaker state
        service.anomaly_detection_breaker.close()

        for i in range(failures):
            with patch.object(service._anomaly_detection_client, "post",
                              side_effect=httpx.ConnectError("fail")):
                with pytest.raises(httpx.ConnectError):
                    service._call_anomaly_detection(sample_telemetry)

            if i < settings.CIRCUIT_BREAKER_FAIL_THRESHOLD - 1:
                assert service.anomaly_detection_breaker.state == "closed"
            else:
                assert service.anomaly_detection_breaker.state == "open"

    @pytest.mark.parametrize("batch_size", [1, 2, 5, 10])
    def test_batch_processing_property(self, service, sample_telemetry, batch_size, monkeypatch):
        """All items must be processed regardless of batch size."""
        monkeypatch.setattr(settings, "PROCESSING_BATCH_SIZE", batch_size)
        total_items = 23  # Non-multiple of batch sizes

        for _ in range(total_items):
            service.ingest(sample_telemetry)

        processed = []
        async def mock_process(batch):
            processed.extend(batch.items)
            return True

        with patch.object(service, "_process_batch", new_callable=AsyncMock, side_effect=mock_process):
            service.start_processing()
            asyncio.get_event_loop().run_until_complete(asyncio.sleep(0.5))
            service.stop_processing()

        assert len(processed) == total_items
        assert service.telemetry_queue.empty()


